import Model from 'flarum/common/Model';
/** A sticker in a set (sticker-book-stickers, admins only). Without art (small null) it is in no pack. */
export default class Sticker extends Model {
  name() {
    return Model.attribute('name').call(this);
  }
  rarity() {
    return Model.attribute('rarity').call(this);
  }
  position() {
    return Model.attribute('position').call(this);
  }
  full() {
    return Model.attribute('full').call(this);
  }
  small() {
    return Model.attribute('small').call(this);
  }
  /** Members holding at least one. */
  ownerCount() {
    return Model.attribute('ownerCount').call(this);
  }
  set() {
    return Model.hasOne('set').call(this) || null;
  }
}
flarum.reg.add('ernestdefoe-sticker-book', 'common/models/Sticker', Sticker);