import Model from 'flarum/common/Model';
/** A set of stickers (sticker-book-sets, admins only). Hidden while it is a draft. */
export default class StickerSet extends Model {
  name() {
    return Model.attribute('name').call(this);
  }
  description() {
    return Model.attribute('description').call(this);
  }
  badgeId() {
    return Model.attribute('badgeId').call(this);
  }
  isHidden() {
    return Model.attribute('isHidden').call(this);
  }
  position() {
    return Model.attribute('position').call(this);
  }
  /** In order; a sticker deleted since the set was loaded is left out. */
  stickers() {
    return (Model.hasMany('stickers').call(this) || []).filter(s => !!s);
  }
}
flarum.reg.add('ernestdefoe-sticker-book', 'common/models/StickerSet', StickerSet);