import app from 'flarum/forum/app';
import { extend } from 'flarum/common/extend';
import Button from 'flarum/common/components/Button';
import LinkButton from 'flarum/common/components/LinkButton';
import Link from 'flarum/common/components/Link';
import Icon from 'flarum/common/components/Icon';
import { rarityName, status, t, logIn } from './util';
export { default as extend } from './extend';

/*
 * forum.js is loaded on every page, so it only wires things up: the pack
 * button, the sidebar link, the profile tab and strip, the trade notification
 * setting and the stickers under posts (the routes are in extend.ts). The
 * pages, the pack reveal and the forms are chunks fetched when first opened.
 */

const openPacks = () => import(/* webpackChunkName: 'forum/components/Reveal', webpackMode: 'lazy-once' */ './components/Reveal').then(r => r.openPacks());
app.initializers.add('ernestdefoe-sticker-book', () => {
  addSidebarLink();
  addPackButton();
  mountPackFab();
  addProfileItems();
  addNotificationSetting();
  addPostStickers();
});
function addSidebarLink() {
  extend('flarum/forum/components/IndexSidebar', 'navItems', function (items) {
    if (!app.forum.attribute('stickerCanView') || !app.forum.attribute('stickerNav')) return;
    const waiting = status()?.packs || 0;
    items.add('stickers', m(LinkButton, {
      href: app.route('stickers'),
      icon: "fas fa-note-sticky"
    }, t('nav'), waiting ? m("span", {
      className: "Button-badge StickerNav-badge"
    }, waiting) : null), 78);
  });
}

// The pack button: shown while a pack waits, glowing for the free daily one.
function addPackButton() {
  extend('flarum/forum/components/HeaderSecondary', 'items', function (items) {
    const s = status();
    if (!s?.packs) return;
    items.add('stickerPacks', m(Button, {
      className: `Button Button--flat StickerPackButton ${s.daily ? 'is-daily' : ''}`,
      onclick: openPacks,
      "aria-label": t('header.label', {
        count: s.packs
      }),
      title: t('header.label', {
        count: s.packs
      })
    }, m(Icon, {
      name: "fas fa-note-sticky"
    }), m("span", {
      className: "StickerPackButton-count"
    }, s.packs)), 15);
  });
}

// On phones the header's buttons live in the drawer, so a waiting pack also floats in a corner.
function mountPackFab() {
  const fab = document.createElement('div');
  fab.className = 'StickerFab-host';
  document.body.appendChild(fab);
  m.mount(fab, {
    view: () => {
      const s = status();
      if (!s?.packs || app.composer?.isVisible?.() || document.body.classList.contains('StickerReveal-open')) return null;
      return m("button", {
        className: `StickerFab ${s.daily ? 'is-daily' : ''}`,
        onclick: openPacks,
        "aria-label": t('header.label', {
          count: s.packs
        })
      }, m(Icon, {
        name: "fas fa-note-sticky"
      }), m("span", {
        className: "StickerPackButton-count"
      }, s.packs));
    }
  });
}
function addProfileItems() {
  extend('flarum/forum/components/UserPage', 'navItems', function (items) {
    if (!this.user || !app.forum.attribute('stickerCanView')) return;
    items.add('stickers', m(LinkButton, {
      href: app.route('user.stickers', {
        username: this.user.slug()
      }),
      icon: "fas fa-note-sticky"
    }, t('profile.nav')), 84);
  });

  // The rarest stickers, on the profile's card (only the profile's own request carries them).
  extend('flarum/forum/components/UserCard', 'infoItems', function (items) {
    // UserCard's attrs are untyped in core; it always gets a `user`.
    const user = this.attrs.user;
    const showcase = user.attribute('stickerShowcase');
    if (!showcase?.top?.length) return;
    items.add('stickers', m(Link, {
      className: "StickerShowcase",
      href: app.route('user.stickers', {
        username: user.slug()
      })
    }, m("span", {
      className: "StickerShowcase-row"
    }, showcase.top.map(s => m("span", {
      className: `StickerShowcase-item StickerShowcase--r${s.rarity}`,
      title: `${s.name} · ${rarityName(s.rarity)}`
    }, m("img", {
      src: s.small,
      alt: s.name
    })))), m("span", {
      className: "StickerShowcase-text"
    }, t('profile.showcase', {
      count: showcase.unique,
      total: showcase.total
    }))), -20);
  });
}
function addNotificationSetting() {
  extend('flarum/forum/components/NotificationGrid', 'notificationTypes', function (items) {
    if (!app.forum.attribute('stickerCanTrade')) return;
    items.add('stickerTrade', {
      name: 'stickerTrade',
      icon: 'fas fa-right-left',
      label: t('notification.preference')
    });
  });
}

// Stickers on posts. The post redraws when its stickers change (its subtree check), not otherwise.
function addPostStickers() {
  extend('flarum/forum/components/CommentPost', 'oninit', function () {
    this.subtree.check(() => this.attrs.post.attribute('stickerReactions'));
  });
  extend('flarum/forum/components/CommentPost', 'footerItems', function (items) {
    const post = this.attrs.post;
    const reactions = post.attribute('stickerReactions');
    if (!reactions?.length || post.isHidden()) return;
    items.add('stickers', m("div", {
      className: "StickerReactions"
    }, reactions.map(r => reactionButton(post, r))), 15);
  });
  extend('flarum/forum/components/CommentPost', 'actionItems', function (items) {
    const post = this.attrs.post;
    if (post.isHidden() || !app.forum.attribute('stickerCanReact')) return;
    items.add('sticker', m(Button, {
      className: "Button Button--link StickerReactButton",
      icon: "far fa-note-sticky",
      onclick: () => app.session.user ? app.modal.show(() => import(/* webpackChunkName: 'forum/components/ReactionModal', webpackMode: 'lazy-once' */ './components/ReactionModal'), {
        post
      }) : logIn()
    }, t('react.button')), -5);
  });
}

/** One sticker under a post: tap to add yours, or take it off again. */
function reactionButton(post, r) {
  const canReact = app.session.user && app.forum.attribute('stickerCanReact');
  return m("button", {
    className: `StickerReaction StickerReaction--r${r.rarity} ${r.mine ? 'is-mine' : ''}`,
    title: `${r.name} · ${rarityName(r.rarity)}`,
    "aria-pressed": r.mine ? 'true' : 'false',
    disabled: !canReact,
    onclick: () => import(/* webpackChunkName: 'forum/components/ReactionModal', webpackMode: 'lazy-once' */ './components/ReactionModal').then(({
      react
    }) => react(post, r.mine ? null : r.id))
  }, m("img", {
    src: r.small,
    alt: r.name,
    loading: "lazy"
  }), r.count > 1 ? m("span", {
    className: "StickerReaction-n"
  }, r.count) : null);
}flarum.reg.addChunkModule('ernestdefoe-sticker-book:forum/components/Reveal', '620', 'ernestdefoe-sticker-book', 'forum/components/Reveal');
flarum.reg.addChunkModule('ernestdefoe-sticker-book:forum/components/ReactionModal', '516', 'ernestdefoe-sticker-book', 'forum/components/ReactionModal');
flarum.reg.addChunkModule('ernestdefoe-sticker-book:forum/components/Reveal', '620', 'ernestdefoe-sticker-book', 'forum/confetti');